// RoundTripTests.swift
// SwiftRepartoTests
//
// Sortie 10: the RQ-11 acceptance gate.
//
// `generate(parse(x)) == x`, asserted by SHA-256 rather than by string
// equality, because the requirement says SHA-256 and because a hash comparison
// cannot be weakened by accident: `XCTAssertEqual` on two `String`s compares
// under Unicode canonical equivalence, so a document that gained or lost a
// combining mark could pass. Hashing `Data(x.utf8)` compares the bytes that
// would actually land in the file.
//
// THE EIGHT DOCUMENTS ARE GENERATED BY THE LIBRARY, NOT HAND-WRITTEN, AND THAT
// IS NOT A CONVENIENCE.
//
// RQ-11 scopes identity to "any `x` this library emitted, and every pinned
// fixture". A hand-written `x` is neither until it has been through one
// emission: declared keys emit in `CodingKeys` declaration order rather than in
// whatever order a human typed them, `voiceDescription:` re-emits as
// `voicePrompt:`, a scalar `voices` value re-emits as a sequence, an
// unversioned document gains `schemaVersion: 1`, and a plain scalar that would
// re-resolve as a boolean or a number comes back single-quoted (see the dialect
// block in `YAMLCoding.swift`). Every one of those is a *correct* first-write
// normalization, and every one of them would fail a byte gate applied to
// hand-typed input for reasons that have nothing to do with round-trip
// identity. So each case below builds a `CastDocument` in memory, emits it
// once to obtain `x`, and then gates on `x`.
//
// CRLF IS DELIBERATELY ABSENT FROM THIS FILE.
//
// A CRLF source round-trips to a *mixed* document: the body keeps its CRLFs
// (D-10, correct, and asserted in `CastMarkdownParserTests`), while the front
// matter is re-emitted by an encoder pinned to `lineBreak = .ln`. That document
// is byte-stable from its first emission onward but is not byte-identical to
// the CRLF file it came from, so CRLF belongs to the body-preservation tests
// and not to this gate.

import CryptoKit
import Foundation
import SwiftReparto
import XCTest

final class RoundTripTests: XCTestCase {

  private let parser = CastMarkdownParser()

  // MARK: - Hashing

  /// The SHA-256 of a string's UTF-8 bytes, hex-encoded.
  ///
  /// `Data(string.utf8)` and not `string.data(using:)`: the former cannot fail
  /// and cannot prepend a BOM, so what is hashed is exactly what
  /// ``CastMarkdownParser/write(document:to:)`` puts on disk.
  private func sha256(_ string: String) -> String {
    SHA256.hash(data: Data(string.utf8))
      .map { String(format: "%02x", $0) }
      .joined()
  }

  // MARK: - Temporary files

  private var temporaryDirectories: [URL] = []

  override func tearDownWithError() throws {
    for directory in temporaryDirectories {
      try? FileManager.default.removeItem(at: directory)
    }
    temporaryDirectories.removeAll()
    try super.tearDownWithError()
  }

  private func makeTemporaryDirectory() throws -> URL {
    let directory = URL.temporaryDirectory.appending(
      path: "SwiftRepartoRoundTrip-\(UUID().uuidString)",
      directoryHint: .isDirectory)
    try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
    temporaryDirectories.append(directory)
    return directory
  }

  // MARK: - The eight documents

  /// The corpus the identity gate runs over, each paired with the name that
  /// will be printed if it fails.
  ///
  /// The eight are chosen so that every byte-level hazard this library knows
  /// about appears at least once: an empty roster, an empty body, a body with
  /// no final newline, a body containing the front-matter delimiter itself,
  /// non-ASCII, prose long enough to tempt the emitter into folding it, a
  /// member with several providers and several paths each, and a set of
  /// undeclared values whose spellings YAML 1.1 would have rewritten.
  private static func corpus() throws -> [(name: String, document: CastDocument)] {
    [
      ("minimal roster", minimalRoster()),
      ("fully populated member", fullyPopulatedMember()),
      ("unicode and long prose", try unicodeAndLongProse()),
      ("body containing delimiters", bodyContainingDelimiters()),
      ("body without a final newline", bodyWithoutFinalNewline()),
      ("empty roster", emptyRoster()),
      ("several providers and paths", severalProvidersAndPaths()),
      ("awkward undeclared scalars", try awkwardUndeclaredScalars()),
    ]
  }

  /// One member, one field, no body. The smallest document that is still a
  /// document.
  private static func minimalRoster() -> CastDocument {
    CastDocument(cast: [CastMember(character: "NARRATOR")], body: "")
  }

  /// Every declared field populated at once, so the `CodingKeys` emission order
  /// — `character`, `actor`, `gender`, `language`, `voicePrompt`, `voices` — is
  /// exercised end to end rather than in fragments.
  private static func fullyPopulatedMember() -> CastDocument {
    CastDocument(
      cast: [
        CastMember(
          character: "THE PRACTITIONER",
          actor: "Tom Stovall",
          gender: .male,
          language: "en",
          voicePrompt: "Deep authoritative British baritone, unhurried.",
          voices: ["voxalta": ["voices/THE-PRACTITIONER.vox"]])
      ],
      body: "## Major Characters\n\n### THE PRACTITIONER\n\nRecorded in one take.\n")
  }

  /// Non-ASCII names, an em dash, and a `bio` long enough that the encoder's
  /// `width = -1` setting is load-bearing: at libyaml's default width this
  /// scalar folds across several lines and stops being byte-stable.
  private static func unicodeAndLongProse() throws -> CastDocument {
    var member = CastMember(
      character: "JOSÉ",
      actor: "José Ramírez",
      gender: .male,
      language: "es-MX",
      voicePrompt:
        "Warm, mid-range, faintly amused — the voice of someone who has heard this story before.",
      voices: ["voxalta": ["voices/JOSE.vox"]])
    member.setExtra(
      try AnyCodable(
        "A stage actor for eleven years before anyone put a microphone in front of him, José "
          + "reads a page the way a musician reads a chart: he is looking for where the line "
          + "turns, and he will find it on the second pass whether or not the director has "
          + "asked for one. He does not warm up. He does not mark. He arrives having already "
          + "decided what the scene is about, and the argument about that — when there is one "
          + "— is the fastest part of the day."),
      forKey: "bio")
    return CastDocument(cast: [member], body: "## Notes\n\nSpanish-language episodes only.\n")
  }

  /// A body carrying the very sequences the split scans for.
  ///
  /// The `---` line inside this body is body, not a delimiter, and a generator
  /// that re-derived the split by searching rather than by concatenation would
  /// be caught here.
  private static func bodyContainingDelimiters() -> CastDocument {
    CastDocument(
      cast: [CastMember(character: "NARRATOR", actor: "Tom Stovall")],
      body: """
        ## Notes

        ---

        A horizontal rule above, four hyphens below.

        ----

        And an example of the file's own header:

        ```
        ---
        type: cast
        ---
        ```

        """)
  }

  /// A body whose last byte is not a newline.
  ///
  /// Written with explicit concatenation rather than a multiline literal
  /// because a `"""` literal always ends its last line, which is precisely the
  /// property under test.
  private static func bodyWithoutFinalNewline() -> CastDocument {
    CastDocument(
      cast: [CastMember(character: "NARRATOR", language: "en")],
      body: "## Notes\n\nNo trailing newline after this sentence.")
  }

  /// `cast: []` with a real body. A valid, fully-parsed document with no
  /// members — never a parse failure (RQ-12).
  private static func emptyRoster() -> CastDocument {
    CastDocument(cast: [], body: "## Major Characters\n\nNone cast yet.\n")
  }

  /// Several providers across the roster, several paths within one provider,
  /// and a member alongside them that has no voices at all.
  ///
  /// The empty `voices` on `SILENT EXTRA` is the deliberate shape decided in
  /// this sortie: `CastMember.encode(to:)` writes `voices` unconditionally, so
  /// a member with none emits `voices: {}` rather than omitting the key. See
  /// ``testMemberWithoutVoicesEmitsAnEmptyMapping``.
  ///
  /// **No member here carries more than one provider, and that is a constraint
  /// this corpus is under rather than a gap in it.** `CastMember.voices` is a
  /// `[String: [String]]` written with a plain `container.encode`, so its
  /// emitted key order is Swift's dictionary iteration order — which is seeded
  /// per process and is not even stable between two dictionaries holding the
  /// same keys within one process. Two providers on one member therefore do not
  /// satisfy a byte gate today. See
  /// ``testTwoProvidersOnOneMemberRoundTripByValueButNotYetByBytes`` for the
  /// pinned statement of that, and the report for the one-line fix it needs.
  /// The *paths* inside a provider are an `Array` and are ordered, so multiple
  /// paths are byte-stable and are exercised here.
  private static func severalProvidersAndPaths() -> CastDocument {
    CastDocument(
      cast: [
        CastMember(
          character: "NARRATOR",
          actor: "Tom Stovall",
          voices: ["voxalta": ["voices/NARRATOR.vox", "voices/NARRATOR-alt.vox"]]),
        CastMember(
          character: "THE PRACTITIONER",
          language: "en",
          voices: ["elevenlabs": ["voices/THE-PRACTITIONER-11.vox"]]),
        CastMember(character: "SILENT EXTRA"),
      ],
      body: "## Minor Characters\n\n### SILENT EXTRA\n\nNo lines.\n")
  }

  /// Undeclared keys whose values YAML 1.1 would have retyped, plus a few the
  /// emitter has to quote for its own reasons.
  ///
  /// Every one of these is a `String` in the model. What the gate proves is
  /// that whatever spelling the emitter chooses for them, it chooses the *same*
  /// spelling on the second pass — which is the property a fixture depends on.
  private static func awkwardUndeclaredScalars() throws -> CastDocument {
    var member = CastMember(character: "NARRATOR")
    member.setExtra(try AnyCodable("no"), forKey: "retired")
    member.setExtra(try AnyCodable("0755"), forKey: "code")
    member.setExtra(try AnyCodable("12:34"), forKey: "cue")
    member.setExtra(try AnyCodable("1_000"), forKey: "takes")
    member.setExtra(try AnyCodable("#1 in the call sheet"), forKey: "billing")
    member.setExtra(try AnyCodable("prefix: suffix"), forKey: "colonized")
    member.setExtra(try AnyCodable("  padded  "), forKey: "padded")
    member.setExtra(try AnyCodable(180), forKey: "sessionMinutes")
    return CastDocument(cast: [member], body: "## Notes\n")
  }

  // MARK: - RQ-11: round-trip identity, by SHA-256

  /// `SHA256(generate(parse(x))) == SHA256(x)` for every document in the
  /// corpus, where each `x` is itself library-emitted.
  func testEveryEmittedDocumentRoundTripsToTheSameBytes() throws {
    let corpus = try Self.corpus()
    XCTAssertEqual(corpus.count, 8, "The gate is specified over eight documents.")

    for (name, document) in corpus {
      let emitted = try parser.generate(document: document)
      let reparsed = try parser.parse(content: emitted)
      let regenerated = try parser.generate(document: reparsed)

      XCTAssertEqual(
        sha256(regenerated), sha256(emitted),
        """
        Round-trip identity failed for "\(name)".

        --- emitted ---
        \(emitted)
        --- regenerated ---
        \(regenerated)
        --- end ---
        """)
    }
  }

  /// Identity is a fixed point, not a coincidence of the first pass: three
  /// successive round trips produce the same bytes as one.
  func testRoundTripIsAFixedPointAcrossRepeatedPasses() throws {
    for (name, document) in try Self.corpus() {
      var current = try parser.generate(document: document)
      let first = current

      for pass in 1...3 {
        current = try parser.generate(document: try parser.parse(content: current))
        XCTAssertEqual(sha256(current), sha256(first), "\(name), pass \(pass)")
      }
    }
  }

  /// Every document in the corpus is genuinely distinct, so a generator that
  /// emitted a constant would fail the gate rather than sail through it.
  func testCorpusDocumentsAreDistinct() throws {
    var digests: Set<String> = []
    for (name, document) in try Self.corpus() {
      let digest = sha256(try parser.generate(document: document))
      XCTAssertTrue(digests.insert(digest).inserted, "\(name) duplicates another document")
    }
  }

  // MARK: - Emission shape (D-12)

  /// The front matter opens with `type`, then `schemaVersion`, then `cast`, in
  /// that order and no other.
  ///
  /// Asserted on the generated string, on the leading bytes, because the order
  /// is a byte-level property that `sortKeys = false` plus `CodingKeys`
  /// declaration order exists to produce. A lexicographic sort would emit
  /// `cast`, `schemaVersion`, `type` and fail here immediately.
  func testFrontMatterKeyOrderIsTypeThenVersionThenCast() throws {
    for (name, document) in try Self.corpus() {
      let emitted = try parser.generate(document: document)
      XCTAssertTrue(
        emitted.hasPrefix("---\ntype: cast\nschemaVersion: 1\ncast:"),
        "\(name) did not open with type/schemaVersion/cast:\n\(emitted.prefix(120))")
    }
  }

  /// The delimiter lines carry no trailing whitespace.
  ///
  /// The parser tolerates it on the way in — a hand-edited file with an
  /// invisible trailing space is still a cast document — and identity requires
  /// that the writer never produce it.
  func testDelimiterLinesCarryNoTrailingWhitespace() throws {
    for (name, document) in try Self.corpus() {
      let emitted = try parser.generate(document: document)
      XCTAssertTrue(emitted.hasPrefix("---\n"), "\(name): opening delimiter")
      XCTAssertFalse(emitted.contains("--- \n"), "\(name): trailing space after a delimiter")
      XCTAssertFalse(emitted.contains("---\t\n"), "\(name): trailing tab after a delimiter")
      XCTAssertTrue(emitted.contains("\n---\n"), "\(name): closing delimiter on its own line")
    }
  }

  /// The body is appended raw: the generated document ends with exactly the
  /// document's body bytes, and nothing is inserted between the closing
  /// delimiter's newline and the body's first byte.
  func testBodyIsAppendedVerbatimAfterTheClosingDelimiter() throws {
    for (name, document) in try Self.corpus() {
      let emitted = try parser.generate(document: document)
      XCTAssertEqual(
        Array(try parser.parse(content: emitted).body.utf8), Array(document.body.utf8),
        "\(name): body bytes changed on emission")
    }
  }

  // MARK: - Acceptance criterion 4: mutate and write

  /// Parsing, mutating `cast[0].voices`, and regenerating leaves the body's
  /// bytes untouched.
  ///
  /// The mutation is the one a real consumer makes — SwiftEchada assigning a
  /// freshly synthesized `.vox` — and the body under it is the one most likely
  /// to be damaged: it has a delimiter in it, a trailing blank line, and CRLF
  /// nowhere near it to hide behind.
  func testMutatingVoicesLeavesTheBodyByteIdentical() throws {
    let original = try parser.generate(document: Self.bodyContainingDelimiters())
    let originalBody = try parser.parse(content: original).body

    var document = try parser.parse(content: original)
    document.cast[0].voices["voxalta"] = ["voices/NARRATOR.vox"]
    let mutated = try parser.generate(document: document)

    let mutatedBody = try parser.parse(content: mutated).body

    XCTAssertEqual(sha256(mutatedBody), sha256(originalBody))
    XCTAssertEqual(Array(mutatedBody.utf8), Array(originalBody.utf8))
    XCTAssertNotEqual(sha256(mutated), sha256(original), "the front matter should have changed")
    XCTAssertTrue(mutated.contains("- voices/NARRATOR.vox"))
  }

  /// The same cycle through the filesystem, which is how a consumer actually
  /// performs it: read a file, change one member, write it back.
  func testMutateAndWriteCycleThroughDiskPreservesTheBody() throws {
    let directory = try makeTemporaryDirectory()
    let fileURL = directory.appending(path: "CAST.md")

    let original = try parser.generate(document: try Self.unicodeAndLongProse())
    try Data(original.utf8).write(to: fileURL)
    let originalBody = try parser.parse(fileURL: fileURL).body

    var document = try parser.parse(fileURL: fileURL)
    document.cast[0].voices = ["apple": ["voices/JOSE-apple.vox"]]
    try parser.write(document: document, to: fileURL)

    let rewritten = try parser.parse(fileURL: fileURL)
    XCTAssertEqual(sha256(rewritten.body), sha256(originalBody))
    XCTAssertEqual(Array(rewritten.body.utf8), Array(originalBody.utf8))
    XCTAssertEqual(rewritten.cast[0].voices, ["apple": ["voices/JOSE-apple.vox"]])
    XCTAssertEqual(rewritten.cast[0][extra: "bio"], document.cast[0][extra: "bio"])
  }

  // MARK: - D-5 / D-12: the version-stamping path

  /// The legacy front matter this library must keep reading: no
  /// `schemaVersion` key at all.
  private static let unversionedSource = """
    ---
    type: cast
    cast:
      - character: NARRATOR
        actor: Tom Stovall
        voiceDescription: Deep authoritative British baritone.
        voices:
          voxalta: voices/NARRATOR.vox
    ---
    ## Notes

    Written before this library existed.

    """

  /// An unversioned document parses as legacy, is stamped on its first write,
  /// and is byte-stable from that write onward.
  func testUnversionedDocumentIsStampedOnceAndIsStableThereafter() throws {
    let legacy = try parser.parse(content: Self.unversionedSource)
    XCTAssertTrue(legacy.isUnversioned)
    XCTAssertEqual(legacy.schemaVersion, CastSchemaVersion.unversioned)

    let firstWrite = try parser.generate(document: legacy)
    XCTAssertTrue(firstWrite.contains("\nschemaVersion: 1\n"))
    XCTAssertNotEqual(
      sha256(firstWrite), sha256(Self.unversionedSource),
      "stamping a version must change the bytes")

    let reparsed = try parser.parse(content: firstWrite)
    XCTAssertEqual(reparsed.schemaVersion, CastSchemaVersion.current)
    XCTAssertFalse(reparsed.isUnversioned)

    let secondWrite = try parser.generate(document: reparsed)
    XCTAssertEqual(sha256(secondWrite), sha256(firstWrite))
  }

  /// A document that *declares* an unsupported-but-past version is not a case
  /// this build has — `current` is 1 — but a document constructed in memory
  /// carrying the legacy sentinel still emits the current version, because the
  /// stamp does not consult the property.
  func testEmissionIgnoresTheDocumentsOwnSchemaVersion() throws {
    let document = CastDocument(
      cast: [CastMember(character: "NARRATOR")],
      body: "",
      schemaVersion: CastSchemaVersion.unversioned)
    let emitted = try parser.generate(document: document)
    XCTAssertTrue(emitted.contains("\nschemaVersion: 1\n"))
  }

  /// The stamped version is never zero-padded.
  ///
  /// `schemaVersion: 01` is a `String` under this library's dialect and fails
  /// to decode as an `Int` (see `YAMLCoding.swift`), so emitting a padded
  /// version would produce a file this library could not read back.
  func testStampedVersionIsNeverPadded() throws {
    for (name, document) in try Self.corpus() {
      let emitted = try parser.generate(document: document)
      XCTAssertTrue(emitted.contains("schemaVersion: 1\n"), name)
      XCTAssertFalse(emitted.contains("schemaVersion: 01"), name)
      XCTAssertFalse(emitted.contains("schemaVersion: '1'"), name)
    }
  }

  // MARK: - RQ-3: `voices` normalizes to the array form

  /// A source document using the scalar form re-emits as a sequence.
  func testScalarVoicesEmitAsTheArrayForm() throws {
    let source = """
      ---
      type: cast
      schemaVersion: 1
      cast:
        - character: NARRATOR
          voices:
            voxalta: voices/NARRATOR.vox
      ---

      """

    let emitted = try parser.generate(document: try parser.parse(content: source))

    XCTAssertTrue(
      emitted.contains("- voices/NARRATOR.vox"),
      "the scalar form must be re-emitted as a sequence:\n\(emitted)")
    XCTAssertFalse(
      emitted.contains("voxalta: voices/NARRATOR.vox"),
      "the scalar form must not survive emission:\n\(emitted)")

    // And the normalized output is itself a fixed point.
    let regenerated = try parser.generate(document: try parser.parse(content: emitted))
    XCTAssertEqual(sha256(regenerated), sha256(emitted))
  }

  /// The decided shape for a member with no voices: the key is present and
  /// empty, not absent.
  ///
  /// `CastMember.encode(to:)` uses `encode`, not `encodeIfPresent`, so `voices`
  /// is always written. A hand-written member with no `voices:` key therefore
  /// gains `voices: {}` on its first write — the same class of one-time
  /// normalization as gaining `schemaVersion: 1` and as `voiceDescription:`
  /// becoming `voicePrompt:`. It is asserted here so that a change to it is a
  /// deliberate schema decision and not a silent one.
  func testMemberWithoutVoicesEmitsAnEmptyMapping() throws {
    let emitted = try parser.generate(document: Self.minimalRoster())
    XCTAssertTrue(emitted.contains("voices: {}"), emitted)

    let normalized = try parser.generate(document: try parser.parse(content: emitted))
    XCTAssertEqual(sha256(normalized), sha256(emitted))
  }

  /// A member carrying two or more providers round-trips its **values**
  /// intact, and — today — not necessarily its **bytes**.
  ///
  /// THIS TEST PINS A KNOWN DEFECT. IT IS NOT A DESIGN STATEMENT.
  ///
  /// ``CastMember/voices`` is `[String: [String]]`, and
  /// `CastMember.encode(to:)` writes it with a plain
  /// `container.encode(voices, forKey: .voices)`. That encodes a Swift
  /// `Dictionary` in its own iteration order, which is derived from a
  /// per-process random hash seed and from the storage capacity the dictionary
  /// happens to have — so the same two providers emit in one order when the
  /// dictionary was built from a literal and in another when it was built key
  /// by key by the decoder. Everything else on the emission path already
  /// defends against this: `extraKeys` is written `keys.sorted()`, and
  /// ``AnyCodable`` encodes through `JSONEncoder` with `.sortedKeys`. `voices`
  /// is the one dictionary that was left unsorted.
  ///
  /// The fix belongs in `CastMember.encode(to:)` — write `voices` through a
  /// nested keyed container over `voices.keys.sorted()`, exactly as
  /// `extraKeys` is already written — and that file is frozen for this sortie.
  ///
  /// So this asserts what *is* guaranteed today, which is not nothing: no
  /// provider, path, or ordering *within* a provider is lost, and the document
  /// that comes back is `Equatable`-equal to the one that went out. When the
  /// encoder is fixed, tighten the second half of this test to a SHA-256
  /// comparison and fold the case back into ``corpus()``.
  func testTwoProvidersOnOneMemberRoundTripByValueButNotYetByBytes() throws {
    let document = CastDocument(
      cast: [
        CastMember(
          character: "NARRATOR",
          voices: [
            "voxalta": ["voices/NARRATOR.vox", "voices/NARRATOR-alt.vox"],
            "apple": ["voices/NARRATOR-apple.vox"],
            "elevenlabs": ["voices/NARRATOR-11.vox"],
          ])
      ],
      body: "## Notes\n")

    let emitted = try parser.generate(document: document)
    let reparsed = try parser.parse(content: emitted)

    // Values survive completely: same providers, same paths, same order within
    // each provider, same body.
    XCTAssertEqual(reparsed.cast[0].voices, document.cast[0].voices)
    XCTAssertEqual(reparsed.cast, document.cast)
    XCTAssertEqual(Array(reparsed.body.utf8), Array(document.body.utf8))

    // And every provider reached the file exactly once, so nothing is dropped
    // or duplicated by the unstable ordering — only rearranged.
    for provider in ["voxalta", "apple", "elevenlabs"] {
      XCTAssertEqual(
        emitted.components(separatedBy: "\n    \(provider):\n").count - 1, 1,
        "\(provider) should appear exactly once")
    }

    // Deliberately NOT asserted here:
    //   XCTAssertEqual(sha256(try parser.generate(document: reparsed)), sha256(emitted))
    // It fails, for the reason above. Restore it with the encoder fix.
  }

  // MARK: - D-7: `write` and `generate` agree, byte for byte

  /// The direct regression test for D-7, on the input that would expose a
  /// relativization pass hiding in `write`: a document holding an absolute
  /// path.
  ///
  /// If `write` relativized and `generate` did not, these two byte streams
  /// would differ — and RQ-11's gate, which runs on `generate`, would never
  /// notice, because it never looks at the file.
  func testWriteProducesExactlyTheBytesGenerateReturns() throws {
    let directory = try makeTemporaryDirectory()
    let fileURL = directory.appending(path: "CAST.md")

    let absolutePath = directory.appending(path: "voices/NARRATOR.vox").path(percentEncoded: false)
    let document = CastDocument(
      cast: [CastMember(character: "NARRATOR", voices: ["voxalta": [absolutePath]])],
      body: "## Notes\n")

    let generated = try parser.generate(document: document)
    try parser.write(document: document, to: fileURL)
    let onDisk = try Data(contentsOf: fileURL)

    XCTAssertEqual(Array(onDisk), Array(generated.utf8))
    XCTAssertEqual(sha256(String(decoding: onDisk, as: UTF8.self)), sha256(generated))

    // And the absolute path was emitted verbatim by both, because emission does
    // no path work at all. RQ-6 is satisfied at ingest, not here.
    XCTAssertTrue(generated.contains(absolutePath))
  }

  /// `write` performs no path logic even when the destination directory is
  /// exactly the one that would make the document's absolute path relative.
  ///
  /// The relativization that RQ-6 promises belongs to `parse(fileURL:)`, and
  /// this asserts the division: the file on disk still holds the absolute path
  /// until it is read back through the entry point that knows the directory.
  func testWriteDoesNotRelativizeAgainstItsOwnDestination() throws {
    let directory = try makeTemporaryDirectory()
    let fileURL = directory.appending(path: "CAST.md")

    let absolutePath = directory.appending(path: "voices/NARRATOR.vox").path(percentEncoded: false)
    let document = CastDocument(
      cast: [CastMember(character: "NARRATOR", voices: ["voxalta": [absolutePath]])],
      body: "")

    try parser.write(document: document, to: fileURL)
    let written = try String(contentsOf: fileURL, encoding: .utf8)
    XCTAssertTrue(written.contains(absolutePath), written)

    // Read back through the entry point that does know the directory, and the
    // same path is relative — that is where RQ-6 is enforced.
    let reread = try parser.parse(fileURL: fileURL)
    XCTAssertEqual(reread.cast[0].voices["voxalta"], ["voices/NARRATOR.vox"])
  }

  /// A round trip that goes all the way through the filesystem hashes the same
  /// as the in-memory one.
  func testFileRoundTripMatchesTheInMemoryGate() throws {
    for (name, document) in try Self.corpus() {
      let directory = try makeTemporaryDirectory()
      let fileURL = directory.appending(path: "CAST.md")

      try parser.write(document: document, to: fileURL)
      let first = try Data(contentsOf: fileURL)

      let reparsed = try parser.parse(fileURL: fileURL)
      try parser.write(document: reparsed, to: fileURL)
      let second = try Data(contentsOf: fileURL)

      XCTAssertEqual(Array(second), Array(first), name)
    }
  }

  // MARK: - RQ-7: `write` touches exactly the URL it is handed

  /// `write` creates no directories.
  ///
  /// The observable half of "this method touches exactly one path": a
  /// destination inside a directory that does not exist fails, rather than the
  /// library deciding to build the tree on the caller's behalf. Nothing here
  /// stats, enumerates, or resolves anything either — that is verified by
  /// reading the source, and this is the behavior it produces.
  func testWriteDoesNotCreateMissingDirectories() throws {
    let directory = try makeTemporaryDirectory()
    let missing = directory.appending(path: "does-not-exist", directoryHint: .isDirectory)
    let fileURL = missing.appending(path: "CAST.md")

    XCTAssertThrowsError(
      try parser.write(document: Self.minimalRoster(), to: fileURL))
    XCTAssertFalse(FileManager.default.fileExists(atPath: missing.path(percentEncoded: false)))
  }

  /// `write` leaves the destination directory containing exactly the one file
  /// it was asked to write — no sibling, no leftover temporary.
  func testWriteLeavesNoTemporaryFileBehind() throws {
    let directory = try makeTemporaryDirectory()
    let fileURL = directory.appending(path: "CAST.md")

    try parser.write(document: Self.fullyPopulatedMember(), to: fileURL)

    let contents = try FileManager.default.contentsOfDirectory(
      at: directory, includingPropertiesForKeys: nil)
    XCTAssertEqual(contents.map(\.lastPathComponent), ["CAST.md"])
  }

  // MARK: - RQ-4: undeclared keys survive the gate by name

  /// `bio` specifically, through the public accessor, across a full write and
  /// read.
  func testUndeclaredKeysSurviveEmission() throws {
    let emitted = try parser.generate(document: try Self.unicodeAndLongProse())
    let reparsed = try parser.parse(content: emitted)

    let original = try Self.unicodeAndLongProse().cast[0][extra: "bio"]
    XCTAssertNotNil(original)
    XCTAssertEqual(reparsed.cast[0][extra: "bio"], original)
    XCTAssertTrue(emitted.contains("bio:"))
  }
}
